	'pe_h2' => 'Les personnes que vous rencontrerez.',
	'pe_label' => '(Les sept)',
	'people_h2' => 'Sept personnes font vivre le lodge.',
	'people_label' => '(L\'équipe)',
	'people_lede' => 'Il n\'y a ni comptoir d\'accueil ni personnel de réception : les sept mêmes personnes enseignent, cuisinent, conduisent et répondent aux courriers, si bien que vous connaîtrez chaque prénom dès le premier dîner.',
	'pr1_d' => '3 jours, 2 nuits · pratique du matin et du soir · 2 marches',
	'pr1_n' => 'Retraite Premières Lueurs de Trois Jours',
	'pr1_p' => '540 €',
